float dts(vec2 xy, float sh, float scy, float scx) {
    return abs(fract(sin(xy.x*scx+sh)/scy)-fract(xy.y));
}

float rnd(float x, float n) {
    return fract(1e4*sin(x*10.0+10.0*pow(1.0+x, 2.5)+n*(2.0+x)*(2.0+x)));
}

#define PI 3.1415926538

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    const float n = 21.0;
    float cf = 0.0;
    float a = atan(uv.y, uv.x)/PI;
    float l = length(uv);
    for(float j=0.0;j<n;++j) {
        vec2 p = vec2((l-0.5)*2.0, a);
        float d= dts(p, 3.0*PI*rnd(j,1.0)-(1.0+rnd(j,1.0)*3.0)*iTime/4.0, 55.0+20.0*rnd(j, 0.0), 2.0+rnd(j,4.0)*4.0);;
        d = pow(d,1.5)*1e4;
        d = 2.0/(d+1.0);
        cf += d;
    }
    vec3 col=vec3(clamp(cf*3.0-2.0,0.0,1.0),clamp(cf*3.0-1.0,0.0,1.0), clamp(cf*3.0,0.0,1.0));

    fragColor = vec4(col,1.0);

}
